import argparse
from bisect import bisect
from collections import Counter, defaultdict
from functools import lru_cache
from hashlib import sha256
import html
from itertools import accumulate, product
import json
from math import comb, isclose, log2
from pathlib import Path
import random
import re
from statistics import median
from string import ascii_lowercase

from vs import ivtff, split

ARMS = ('wheel', 'bigram', 'role_order', 'role_trigram', 'thinning_order', 'thinning_trigram')
NAMES = {'ZL': 'ZL3b-n.txt', 'IT': 'IT2a-n.txt', 'RF': 'RF1b-e.txt'}
GRAMMAR_HASH = 'a74a5224544d50f131f5b133023c835ad971dfef4098d4aa883026c7fb42bd55'
ESCAPE = .1
SHARE = .1

def leaf(id_):
    return re.match(r'f\d+', id_)[0]

def runs(page):
    for line in page.lines:
        if line.unit != 'P':
            continue
        run = []
        for word in line.words:
            if re.fullmatch('[a-z]+', word):
                run.append(word)
            elif run:
                yield run
                run = []
        if run:
            yield run

def load_grammar(path):
    raw = path.read_bytes()
    assert sha256(raw).hexdigest() == GRAMMAR_HASH
    text = html.unescape(re.sub(r'<[^>]+>', '', raw.decode()))
    text = text[text.index('NormalWord:'):text.index('AbnormalWord:')]
    grammar = {}
    current = None
    for line in text.splitlines():
        start = re.match(r'^([A-Za-z][A-Za-z0-9]*):\s*$', line)
        if start:
            current = start[1]
            grammar[current] = []
            continue
        row = re.match(r'^\s*\d+\s+[\d.]+\s+[\d.]+\s+(\S+)', line)
        if row and current:
            grammar[current].append(row[1])
    @lru_cache(None)
    def pattern(name):
        if name not in grammar:
            return re.escape(name)
        terms = [''.join(pattern(symbol) for symbol in alt.split('.') if symbol)
                 for alt in grammar[name]]
        return '(?:' + '|'.join(terms) + ')'
    normal = re.compile('^' + pattern('NormalWord') + '$')
    @lru_cache(None)
    def abnormal(word):
        return normal.fullmatch(word) is None
    return abnormal

@lru_cache(None)
def segment(word):
    return tuple(ivtff.segment(word, 'eva-basic'))

@lru_cache(None)
def glen(word):
    return len(segment(word))

@lru_cache(200000)
def edit1(a,b):
    a,b = segment(a), segment(b)
    if abs(len(a)-len(b)) > 1:
        return False
    if len(a) == len(b):
        return sum(x!=y for x,y in zip(a,b)) == 1
    if len(a)>len(b):
        a,b=b,a
    i=0
    while i<len(a) and a[i]==b[i]:
        i+=1
    return a[i:]==b[i+1:]

def tv(a,b):
    total_a,total_b=sum(a.values()),sum(b.values())
    return sum(abs(a[k]/total_a-b[k]/total_b) for k in a.keys()|b.keys())/2

def grams(word, n):
    s='^'+word+'$'
    return zip(*(s[i:] for i in range(n)))

def role_gate(train):
    exposures=Counter()
    counts=defaultdict(Counter)
    for word in train:
        n=len(word)
        if n<3:
            continue
        for i,c in enumerate(word):
            position=3*(2*i+1)//(2*n)
            exposures[position]+=1
            counts[c][position]+=1
    mapping={}
    for char in ascii_lowercase:
        enrich=sorted((((counts[char][k]+.5)/(exposures[k]+.5), k+1)
                       for k in range(3)), reverse=True)
        best, position=enrich[0]
        mapping[char]=position if counts[char].total()>=20 and best>=2*enrich[1][0] else 0
    table=str.maketrans({c:str(k) for c,k in mapping.items()})
    @lru_cache(None)
    def projected(w):
        return w.translate(table)
    @lru_cache(None)
    def ordered(w):
        active=projected(w).replace('0','')
        return all(a<=b for a,b in zip(active, active[1:]))
    support=Counter(t for w in set(train) for t in set(grams(projected(w),3)))
    allowed={t for t,n in support.items() if n>=5}
    @lru_cache(None)
    def trigram(w):
        return all(t in allowed for t in grams(projected(w),3))
    return mapping,allowed,ordered,trigram

def build_wheels(banks, train):
    p=banks['exception_bank_draw_probability']
    bins={}
    theoretical=Counter()
    for name,slots in banks['schedule'].items():
        weight=p if name=='exception_bank' else 1-p
        series=[(tuple(''.join(x) for x in t),glen(''.join(''.join(x) for x in t)))
                for t in product(*slots)]
        for _,length in series:
            theoretical[length]+=weight/len(series)
        bins[name]=series
    target=Counter(map(glen,train))
    weights={n:min(4,max(.25,target[n]/target.total()/q)) for n,q in theoretical.items()}
    populations={name:[t for t,_ in values] for name,values in bins.items()}
    cdfs={name:list(accumulate(weights[n] for _,n in values)) for name,values in bins.items()}
    probability={name:[(p if name=='exception_bank' else 1-p)*weights[n]/cdfs[name][-1]
                       for _,n in values] for name,values in bins.items()}
    return p,weights,theoretical,populations,cdfs,probability

def make_gates(base,train,wheels):
    bigrams={t for w in base for t in grams(w,2)}
    assert len(bigrams)==312
    mapping,trigrams,ordered,trigram=role_gate(train)
    @lru_cache(None)
    def bigram(word):
        return all(t in bigrams for t in grams(word,2))
    _,_,_,pop,_,proposal=wheels
    by_len=Counter()
    accepts=[Counter(),Counter()]
    for name,population in pop.items():
        for fragments, weight in zip(population,proposal[name]):
            w=''.join(fragments)
            n=glen(w)
            by_len[n]+=weight
            for i, gate in enumerate((ordered,trigram)):
                accepts[i][n]+=weight*(1 if gate(w) else ESCAPE)
    assert abs(by_len.total()-1)<1e-10
    rates=[{n:a[n]/by_len[n] for n in by_len} for a in accepts]
    # Sharing can change length, so use the overall proposal rate if it
    # creates a length outside the unshared support.
    defaults=[a.total() for a in accepts]
    @lru_cache(None)
    def shadow_order(word):
        return rates[0].get(glen(word),defaults[0])
    @lru_cache(None)
    def shadow_trigram(word):
        return rates[1].get(glen(word),defaults[1])
    predicates=dict(bigram=bigram,role_order=ordered,role_trigram=trigram)
    probability={name:(lambda w,func=fn: 1 if func(w) else ESCAPE)
                 for name, fn in predicates.items()}
    probability.update(wheel=lambda _:1,thinning_order=shadow_order,thinning_trigram=shadow_trigram)
    cost=dict(wheel=0,bigram=728,role_order=52,role_trigram=152)
    return predicates,probability,dict(enumerative_bigram_width=log2(comb(728,312))+10,
        gate_bits=cost,role_map=mapping,projection_mask=sorted(''.join(t) for t in trigrams),
        projected_trigram_count=len(trigrams),unshared_length_thinning_rates=rates,
        unshared_rates=defaults)

def unshared_proposal_diagnostics(wheels, probability, abnormal):
    _, _, _, populations, _, proposal_mass = wheels
    admitted = {name: Counter() for name in ARMS}
    exception = Counter()
    for bank, population in populations.items():
        for fragments, mass in zip(population, proposal_mass[bank]):
            word = ''.join(fragments)
            for name, accept in probability.items():
                kept_mass = mass * min(1, accept(word))
                admitted[name][glen(word)] += kept_mass
                exception[name] += kept_mass * abnormal(word)
    for gate, control in (('role_order', 'thinning_order'), ('role_trigram', 'thinning_trigram')):
        assert all(isclose(q, admitted[control][n], abs_tol=1e-12) for n,q in admitted[gate].items())
    return {
        name: dict(acceptance=masses.total(), exception_mass=exception[name]/masses.total())
        for name, masses in admitted.items()
    }

def generate(page_runs, weights, accept, seed):
    p,_,_,pop,cdf,_=weights
    sampled=random.Random(seed)
    thinning=random.Random(seed ^ 0x77702690)
    for folio,seqs in page_runs.items():
        outputs=[]
        tries, rejected, specialist, shared=0,0,0,0
        for real in seqs:
            previous_bank, previous = None, None
            output=[]
            for _ in real:
                while True:
                    tries+=1
                    bank='exception_bank' if sampled.random()<p else 'baseline'
                    position=bisect(cdf[bank],sampled.random()*cdf[bank][-1])
                    fragments=pop[bank][position]
                    share=previous_bank==bank and sampled.random()<SHARE
                    if share:
                        k=sampled.randrange(3)
                        fragments=fragments[:k]+(previous[k],)+fragments[k+1:]
                    word=''.join(fragments)
                    if thinning.random()<min(1,accept(word)):
                        break
                    rejected+=1
                previous_bank,previous=bank,fragments
                output.append(word)
                specialist+=bank=='exception_bank'
                shared+=share
            outputs.append(output)
        yield folio,outputs,(tries,rejected,specialist,shared)

def pair_counts(sequences):
    pairs=defaultdict(Counter)
    for run in sequences:
        for a,b in zip(run,run[1:]):
            key=(glen(a),glen(b))
            pairs[key]['pairs']+=1
            pairs[key]['edit1']+=edit1(a,b)
            pairs[key]['repeat']+=a==b
    return pairs

def rate_estimates(real, model, support):
    total = sum(real[k]['pairs'] for k in support)
    if not total:
        return None
    return {key:sum(real[k]['pairs']*model[k][key]/model[k]['pairs'] for k in support)/total
            for key in ('edit1','repeat')}

def examine(synthetic, real, abnormal, train_set, support_words, predicates):
    real_words=[w for seqs in real.values() for seq in seqs for w in seq]
    observed_exceptions={w for w in real_words if abnormal(w) and w not in train_set}
    real_pairs=pair_counts(seq for seqs in real.values() for seq in seqs)
    real_lengths=Counter(map(glen,real_words))
    real_types=Counter(map(glen,set(real_words)))
    real_summary=dict(tokens=len(real_words),folios=len(real),
        exception_mass=sum(abnormal(w) for w in real_words)/len(real_words),
        held_apart_exception_types=len(observed_exceptions),
        held_apart_exceptions_in_wheel_support=len(observed_exceptions&support_words))
    seed_out=[]
    leaf_out=defaultdict(dict)
    for seed,arms in synthetic:
        initialized={}
        for name, generated in arms.items():
            counts=Counter()
            folio_stats={}
            all_seq=[]
            for f,seqs,attempt in generated:
                words=[w for row in seqs for w in row]
                m=len(words)
                g=sum(abnormal(w) for w in words)
                folio_stats[f]=(m,g)
                counts.update(dict(zip(('attempts','rejections','specialist','shared'),attempt)))
                all_seq.extend(seqs)
            all_words=[w for seq in all_seq for w in seq]
            vocab=set(all_words)
            total=len(all_words)
            assert total==len(real_words) and counts['attempts']==counts['rejections']+total
            stats=dict(exception_mass=sum(x[1] for x in folio_stats.values())/total,
                       held_apart_exception_types_emitted=len(vocab&observed_exceptions),
                       unseen_emitted_exception_types=sum(abnormal(w) and w not in train_set for w in vocab),
                       attempts_per_token=counts['attempts']/total,
                       accepted_specialist=counts['specialist']/total,accepted_sharing=counts['shared']/total,
                       token_length_tv=tv(real_lengths,Counter(map(glen,all_words))),
                       type_length_tv=tv(real_types,Counter(map(glen,vocab))))
            leaf_out[name][seed]=folio_stats
            initialized[name]=(stats,pair_counts(all_seq))
        common=set(real_pairs).intersection(*(set(m) for _, m in initialized.values()))
        comparison={}
        for name,(stats,m) in initialized.items():
            joint=set(real_pairs)&set(m)
            comparison[name]=dict(**stats, common_match=rate_estimates(real_pairs,m,common),
                     own_supported_fraction=sum(real_pairs[k]['pairs'] for k in joint)/
                                            sum(row['pairs'] for row in real_pairs.values()))
        seed_out.append(dict(seed=seed,arms=comparison,
                             real_common=rate_estimates(real_pairs,real_pairs,common),
                             common_support=sum(real_pairs[k]['pairs'] for k in common)/
                                            sum(row['pairs'] for row in real_pairs.values())))
    seeds=[x['seed'] for x in seed_out]
    bootstrap_ci={}
    id_groups=defaultdict(list)
    for f in real:
        id_groups[leaf(f)].append(f)
    contrasts=[(name,'wheel') for name in ARMS if name!='wheel']
    contrasts.extend([('role_order','thinning_order'),('role_trigram','thinning_trigram')])
    for name, reference in contrasts:
        runs=leaf_out[name]
        rng=random.Random(582334)
        leaf_counts={}
        for l,fs in id_groups.items():
            leaf_counts[l]=[sum(runs[s][f][0] for s in seeds for f in fs),
                            sum(runs[s][f][1]-leaf_out[reference][s][f][1] for s in seeds for f in fs)]
        draws=[]
        for _ in range(4999):
            draw=rng.choices(list(leaf_counts),k=len(leaf_counts))
            draws.append(sum(leaf_counts[l][1] for l in draw)/sum(leaf_counts[l][0] for l in draw))
        draws.sort()
        bootstrap_ci[name+' minus '+reference]=dict(
            seed_mean=sum(n[1] for n in leaf_counts.values())/sum(n[0] for n in leaf_counts.values()),
            leaf_bootstrap_95=[draws[124],draws[4874]])
    means={}
    for name in ARMS:
        view=[z['arms'][name] for z in seed_out]
        means[name]=dict((key,median(a[key] for a in view)) for key in view[0] if key!='common_match')
        means[name].update(common_edit1=median(a['common_match']['edit1'] for a in view),
                           common_repeat=median(a['common_match']['repeat'] for a in view),
                           exception_seed_range=[min(a['exception_mass'] for a in view),
                                                 max(a['exception_mass'] for a in view)])
    hard_support={name:sum(gate(w) for w in support_words&observed_exceptions) for name,gate in predicates.items()}
    return dict(real=real_summary,hard_gate_held_apart_exception_support=hard_support,
                baseline_common_edit1_median=median(x['real_common']['edit1'] for x in seed_out),
                common_layout_support_median=median(x['common_support'] for x in seed_out),
                seed_medians=means,exception_mass_seed_mean_paired_contrasts=bootstrap_ci,
                individual=seed_out)

def main():
    cli=argparse.ArgumentParser()
    cli.add_argument('raw',type=Path)
    cli.add_argument('banks',type=Path)
    cli.add_argument('stolfi',type=Path)
    cli.add_argument('--seeds',type=int,default=10)
    args=cli.parse_args()
    banks=json.loads(args.banks.read_text())
    abnormal=load_grammar(args.stolfi)
    pages={n:list(ivtff.parse(args.raw/f)) for n,f in NAMES.items()}
    ev=set(split.select('practice',pages['ZL']))
    ev_leaves={leaf(f) for f in ev}
    base=[w for p in pages['ZL'] if p.id not in ev for seq in runs(p) for w in seq]
    train=[w for p in pages['ZL'] if leaf(p.id) not in ev_leaves for seq in runs(p) for w in seq]
    weights=build_wheels(banks,base)
    predicates, prob, gate_stats=make_gates(base,train,weights)
    support={''.join(t) for population in weights[3].values() for t in population}
    out=dict(fit=dict(public_tokens=len(base),leaf_disjoint_tokens=len(train),support_words=len(support),
                      baseline_lengths=sorted(weights[2]),shape_fitting='retains inherited P-G-033 weights'),
             gates=gate_stats, input_hashes={n:sha256((args.raw/f).read_bytes()).hexdigest() for n,f in NAMES.items()},
             unshared_proposal_diagnostics=unshared_proposal_diagnostics(weights,prob,abnormal),views={})
    for name,p in pages.items():
        real={z.id:r for z in p if z.id in ev and (r:=list(runs(z)))}
        sims=((seed,{arm:generate(real,weights,prob[arm],seed) for arm in ARMS})
              for seed in range(51001,51001+args.seeds))
        out['views'][name]=examine(sims,real,abnormal,set(base),support,predicates)
    print(json.dumps(out,indent=2))

if __name__=='__main__':
    main()
